#include <bits/stdc++.h>
using namespace std;const int N=105;long long a[N],p[N],w[N],b[N];int main(){ios::sync_with_stdio(0);cin.tie(0);int T;cin>>T;while(T--){int n,m;cin>>n>>m;for(int i=0;i<n;i++)cin>>a[i];for(int i=0;i<n;i++)cin>>p[i];for(int i=0;i<n;i++)cin>>w[i];multiset<long long>s;while(m--){long long x;cin>>x;s.insert(x);}for(int i=0;i<n;i++){auto t=s.upper_bound(a[i]);if(t==s.begin())t=s.begin();else --t;b[i]=*t;s.erase(t);s.insert(w[i]);}long long x;for(x=0;x<=10000000;x++){int i=0;for(;i<n;i++)if(b[i]*x<a[i]||(b[i]*x-a[i])%p[i])break;if(i==n)break;}cout<<(x<=10000000?x:-1)<<'\n';}}
